INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
  (53565, 0, 0, 'One day you will have to teach me your secrets.', 12, 0, 100, 35, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 1, 'You are bound for a great things, trainee.', 12, 0, 100, 35, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 2, 'That target didn''t stand a chance.', 12, 0, 100, 39, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 3, 'I hope the instructors saw that!', 12, 0, 100, 0, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 4, 'Such skill for a new trainee.', 12, 0, 100, 39, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 5, 'I must train harder so I can be like you.', 12, 0, 100, 39, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 0, 6, 'Your form is impeccable.', 12, 0, 100, 35, 0, 0, 0, 0, 'Aspiring Trainee to Training Target'),
  (53565, 1, 0, 'My money''s on Lam. Did you see him take down Chu during training last week?', 12, 0, 100, 39, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 2, 0, 'His stamina is nothing against Lam''s strength.', 12, 0, 100, 35, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 3, 0, 'He has the legs of an ox! Have you ever been kicked by him in training?', 12, 0, 100, 1, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 4, 0, 'Raise you a keg of Stormstout Gold. It''ll be your loss.', 12, 0, 100, 0, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 5, 0, 'That''s where you''re mistaken, friend. Zhou is as sturdy as an oak.', 12, 0, 100, 0, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 6, 0, 'Zhou has the stamina of three men, so he can out-stay most opponents.', 12, 0, 100, 0, 0, 0, 0, 0, 'Aspiring Trainee'),
  (53565, 7, 0, 'Four coppers on Zhou.', 12, 0, 100, 35, 0, 0, 0, 0, 'Aspiring Trainee'),
  (54130, 0, 0, 'Look out! Its friendses are coming!', 14, 0, 100, 2, 0, 0, 0, 0, 'Amberleaf Scamp to Player'),
  (54130, 1, 0, 'Run away!', 14, 0, 100, 2, 0, 0, 0, 0, 'Amberleaf Scamp to Player'),
  (54135, 0, 0, 'You have earned the right to proceed.  Huo lies beyond.', 12, 0, 100, 0, 0, 0, 0, 0, 'Master Li Fei to Player'),
  (54567, 0, 0, 'A challenge in compassion and humility. By helping Merchant Lorvo, it would seem you''ve passed, $c. Master Shang would be pleased.', 12, 0, 100, 2, 0, 0, 0, 0, 'Aysa Cloudsinger to Player'),
  (54567, 1, 0, 'And so our path lays before us. Speak to Master Shang Xi, he will tell you what comes next.', 12, 0, 100, 0, 0, 0, 0, 0, 'Aysa Cloudsinger to Player'),
  (54568, 0, 0, 'Take that monkeybutt!', 12, 0, 100, 5, 0, 0, 0, 0, 'Ji Firepaw to Player'),
  (54586, 0, 0, 'I have never seen a trainee with skills such as yours. I must tell the others.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 1, 'My skills are no match for yours. I admit defeat.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 2, 'Thank you for reminding me that I must train more diligently.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 3, 'That was a good match. Thank you.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 4, 'You are an honorable opponent.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 5, 'You fight honorably, friend.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 6, 'You fought well. I must learn more from you in the future.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
  (54586, 0, 7, 'Your skills are too great. I yield.', 12, 0, 100, 1, 0, 0, 0, 0, 'Trainee'),
